vec3 multiply(vec3 v, mat3 m) { return m * v; }
vec4 multiply(vec4 v, mat4 m) { return m * v; }
vec4 textureBias(sampler2D s, vec4 uv4) { return textureLod(s, uv4.xy, uv4.w); }
vec4 textureLod4(sampler2D s, vec4 uv4) { return textureLod(s, uv4.xy, uv4.w); }
// Custom sampler stubs (mapped to noise texture)
#define sampler_worms sampler_noise_lq
sampler sampler_worms;
vec3 color, mus;
float dx,dy;

void main() {
  vec3 ret = vec3(0.0);
  vec2 uv = vUv;
  vec2 uv_orig = vUvOriginal;
  float rad = vRadius;
  float ang = vAngle;
  vec2 uv1 = (uv-.5) * uAspect.xy;
vec2 uv6 = uv1;
float z = q10 * 24.0*length(((uv1.x)*(uv1.y)));
vec2 d = normalize(uv1);
vec2 rs = clamp(tan(z)*d,-2, 2.0 );
uv += .001*lum(GetBlur1(uv).xy)*vec2( 0.0 , 0.0 );
uv -= rs / 200.0;
uv6 = .4*sin(uv * 5.0+rand_frame * 8.0);
mus = .095/(length(uv6));  // sensit  orig:  .078
mus *= ((audioLow+audioMid)*1.75)*.34*vec3( 1.0 , .575, .9);
vec3 blur = GetBlur2(fract(uv));
vec3 crisp= texture(sampler_main,uv);
vec3 ret1 = crisp - blur*.05 + .1*mus;
q25 = 1;
ret = q25*(ret1*.99-.025) + (1.0 - q25)* GetPixel(uv_orig);
  fragColor = vec4(ret, 1.0);
}

